                    executionId, throwable);
            // WHOLE BULK FAILED
            // mark all the docs as fail
            Iterator<ActionRequest> itreq = request.requests().iterator();
            while (itreq.hasNext()) {
                IndexRequest bir = (IndexRequest) itreq.next();
                String id = bir.id();
                Tuple[] xx = waitAck.remove(id);
                if (xx != null) {
                    for (Tuple x : xx) {
                        LOG.debug("Removed from unacked {}", id);
